%% Test-only helpers that compile and load the runtime FFI module generated by
%% gleam_mutants/runtime.generate, then observe active/0 under different
%% process-local and node-global settings.
-module(runtime_test_ffi).

-export([load_generated/1, active/1, active_in_new_process/1,
         set_process_active/1, erase_process_active/0,
         set_persistent_active/1, erase_persistent_active/0]).

load_generated(Path) ->
    Source = unicode:characters_to_list(Path),
    case compile:file(Source, [binary, return_errors]) of
        {ok, Module, Code} -> load_binary(Module, Source, Code);
        {ok, Module, Code, _Warnings} -> load_binary(Module, Source, Code);
        {error, Errors, _Warnings} -> {error, describe(Errors)};
        error -> {error, <<"compilation failed">>}
    end.

load_binary(Module, Source, Code) ->
    _ = code:purge(Module),
    case code:load_binary(Module, Source, Code) of
        {module, Module} -> {ok, atom_to_binary(Module, utf8)};
        {error, Reason} -> {error, describe(Reason)}
    end.

describe(Term) ->
    unicode:characters_to_binary(io_lib:format("~p", [Term])).

active(Module) ->
    apply(binary_to_atom(Module, utf8), active, []).

active_in_new_process(Module) ->
    Parent = self(),
    Ref = make_ref(),
    _ = spawn(fun() -> Parent ! {Ref, active(Module)} end),
    receive
        {Ref, Value} -> Value
    after 5000 ->
        <<"gleam_mutants_test_timeout">>
    end.

set_process_active(Value) ->
    _ = erlang:put(gleam_mutants_active, Value),
    nil.

erase_process_active() ->
    _ = erlang:erase(gleam_mutants_active),
    nil.

set_persistent_active(Value) ->
    ok = persistent_term:put({gleam_mutants, active}, Value),
    nil.

erase_persistent_active() ->
    _ = persistent_term:erase({gleam_mutants, active}),
    nil.
